// buildingEstimates.js
// Seed estimated FairRent scores for Vancouver and Metro Vancouver buildings.
//
// IMPORTANT: every score in this file is a seed estimate, not a verified
// renter-submitted score. UI must always show it with:
//   - 'Estimated FairRent score'
//   - 'Low confidence' (or 'Very low confidence')
//   - 'Based on available market signals'
//   - 'Needs more renter submissions'
// Replace per-building entries with real scores once a building reaches the
// privacy thresholds (>= 5 submissions for a published score, >= 10 for
// comparison, >= 20 for stronger editorial analysis).
//
// Lookup is by normalized name OR alias; see lookupBuildingEstimate below.

function normalize(s) {
  if (!s) return "";
  return String(s).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, " ").trim();
}

